package tap

import (
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"path/filepath"
	"strconv"
	"strings"
)

const (
	FlagHeader byte = 0x00
	FlagData   byte = 0xff

	BlockTypeProgram     byte = 0
	BlockTypeNumberArray byte = 1
	BlockTypeCharArray   byte = 2
	BlockTypeCode        byte = 3

	HeaderPayloadLength = 19
	MaxBlockPayload     = 0xffff
	MaxDataBytes        = MaxBlockPayload - 2
)

var blockTypeNames = map[byte]string{
	BlockTypeProgram:     "program",
	BlockTypeNumberArray: "number-array",
	BlockTypeCharArray:   "char-array",
	BlockTypeCode:        "code",
}

type Header struct {
	Type       byte   `json:"type"`
	TypeName   string `json:"type_name"`
	Name       string `json:"name"`
	RawName    string `json:"raw_name"`
	DataLength uint16 `json:"data_length"`
	Param1     uint16 `json:"param1"`
	Param2     uint16 `json:"param2"`
}

type Block struct {
	Index            int     `json:"index"`
	Offset           int     `json:"offset"`
	Length           uint16  `json:"length"`
	Flag             *byte   `json:"flag,omitempty"`
	ChecksumStored   *byte   `json:"checksum_stored,omitempty"`
	ChecksumExpected *byte   `json:"checksum_expected,omitempty"`
	ChecksumOK       *bool   `json:"checksum_ok,omitempty"`
	Kind             string  `json:"kind"`
	Header           *Header `json:"header,omitempty"`
	Payload          []byte  `json:"-"`
}

type Archive struct {
	Blocks []Block `json:"blocks"`
}

func Parse(data []byte) (Archive, error) {
	var archive Archive

	for offset := 0; offset < len(data); {
		if len(data)-offset < 2 {
			return archive, fmt.Errorf("truncated length at offset %d: %d byte remains", offset, len(data)-offset)
		}

		length := int(binary.LittleEndian.Uint16(data[offset : offset+2]))
		payloadOffset := offset + 2
		nextOffset := payloadOffset + length
		if nextOffset > len(data) {
			return archive, fmt.Errorf("truncated block at offset %d: declared %d bytes, only %d available", offset, length, len(data)-payloadOffset)
		}

		payload := data[payloadOffset:nextOffset]
		block := Block{
			Index:   len(archive.Blocks),
			Offset:  offset,
			Length:  uint16(length),
			Kind:    "empty",
			Payload: payload,
		}

		if len(payload) > 0 {
			flag := payload[0]
			block.Flag = &flag
			block.Kind = kindForFlag(flag)
		}

		if len(payload) >= 2 {
			stored := payload[len(payload)-1]
			expected := Checksum(payload[:len(payload)-1])
			ok := stored == expected
			block.ChecksumStored = &stored
			block.ChecksumExpected = &expected
			block.ChecksumOK = &ok
		}

		if len(payload) == HeaderPayloadLength && payload[0] == FlagHeader {
			header := ParseHeader(payload)
			block.Header = &header
			block.Kind = "header"
		}

		archive.Blocks = append(archive.Blocks, block)
		offset = nextOffset
	}

	return archive, nil
}

func Read(r io.Reader) (Archive, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return Archive{}, err
	}
	return Parse(data)
}

func Write(w io.Writer, payloads [][]byte) error {
	for i, payload := range payloads {
		if len(payload) > MaxBlockPayload {
			return fmt.Errorf("block %d is too large: %d bytes > %d", i, len(payload), MaxBlockPayload)
		}

		var length [2]byte
		binary.LittleEndian.PutUint16(length[:], uint16(len(payload)))
		if _, err := w.Write(length[:]); err != nil {
			return err
		}
		if _, err := w.Write(payload); err != nil {
			return err
		}
	}
	return nil
}

func Checksum(payloadWithoutChecksum []byte) byte {
	var checksum byte
	for _, b := range payloadWithoutChecksum {
		checksum ^= b
	}
	return checksum
}

func WrapBlock(flag byte, data []byte) ([]byte, error) {
	if len(data) > MaxDataBytes {
		return nil, fmt.Errorf("data block is too large: %d bytes > %d", len(data), MaxDataBytes)
	}

	payload := make([]byte, len(data)+2)
	payload[0] = flag
	copy(payload[1:], data)
	payload[len(payload)-1] = Checksum(payload[:len(payload)-1])
	return payload, nil
}

func HeaderBlock(header Header) ([]byte, error) {
	payload := make([]byte, HeaderPayloadLength)
	payload[0] = FlagHeader
	payload[1] = header.Type

	name, err := FormatName(header.Name)
	if err != nil {
		return nil, err
	}
	copy(payload[2:12], name[:])
	binary.LittleEndian.PutUint16(payload[12:14], header.DataLength)
	binary.LittleEndian.PutUint16(payload[14:16], header.Param1)
	binary.LittleEndian.PutUint16(payload[16:18], header.Param2)
	payload[18] = Checksum(payload[:18])
	return payload, nil
}

func ParseHeader(payload []byte) Header {
	rawName := string(payload[2:12])
	blockType := payload[1]
	return Header{
		Type:       blockType,
		TypeName:   BlockTypeName(blockType),
		Name:       strings.TrimRight(rawName, " "),
		RawName:    rawName,
		DataLength: binary.LittleEndian.Uint16(payload[12:14]),
		Param1:     binary.LittleEndian.Uint16(payload[14:16]),
		Param2:     binary.LittleEndian.Uint16(payload[16:18]),
	}
}

func FormatName(name string) ([10]byte, error) {
	var out [10]byte
	for i := range out {
		out[i] = ' '
	}

	if name == "" {
		return out, errors.New("TAP filename cannot be empty")
	}
	if len([]byte(name)) > len(out) {
		return out, fmt.Errorf("TAP filename %q is too long: maximum is 10 bytes", name)
	}
	for _, r := range name {
		if r < 0x20 || r > 0x7e {
			return out, fmt.Errorf("TAP filename %q must contain printable ASCII only", name)
		}
	}

	copy(out[:], []byte(name))
	return out, nil
}

func BlockTypeName(t byte) string {
	if name, ok := blockTypeNames[t]; ok {
		return name
	}
	return "unknown-" + strconv.Itoa(int(t))
}

func ParseBlockType(name string) (byte, error) {
	normalized := strings.ToLower(strings.TrimSpace(name))
	switch normalized {
	case "program", "basic", "bas":
		return 0, nil
	case "number-array", "number_array", "num-array", "num", "numeric-array":
		return 1, nil
	case "char-array", "char_array", "character-array", "char", "string-array":
		return 2, nil
	case "code", "bytes", "binary", "bin":
		return 3, nil
	default:
		return 0, fmt.Errorf("unknown block type %q", name)
	}
}

func DefaultTapeName(inputPath string) string {
	base := filepath.Base(inputPath)
	ext := filepath.Ext(base)
	if ext != "" {
		base = strings.TrimSuffix(base, ext)
	}
	base = strings.TrimSpace(base)
	if base == "" {
		base = "BINARY"
	}
	base = strings.ToUpper(base)
	if len([]byte(base)) > 10 {
		base = string([]byte(base)[:10])
	}
	return base
}

func kindForFlag(flag byte) string {
	switch flag {
	case FlagHeader:
		return "header-like"
	case FlagData:
		return "data"
	default:
		return fmt.Sprintf("flag-%02x", flag)
	}
}

