#include "ilbm.h"

#include <stdlib.h>
#include <string.h>

/* CAMG ViewMode flags we care about for rendering. */
#define CAMG_LACE   0x0004u
#define CAMG_EHB    0x0080u
#define CAMG_HAM    0x0800u
#define CAMG_HIRES  0x8000u

/* Reader over the BODY chunk that yields one plane-row (rowBytes) at a time,
 * transparently handling ByteRun1 (PackBits) decompression. */
typedef struct {
    const uint8_t *p;
    const uint8_t *end;
    int compressed;
} body_reader_t;

/* Fill dst with exactly n bytes of the next plane-row. Returns 0, or -1 if the
 * BODY is exhausted / malformed. */
static int read_row(body_reader_t *r, uint8_t *dst, int n)
{
    if (!r->compressed) {
        if (r->p + n > r->end)
            return -1;
        memcpy(dst, r->p, (size_t)n);
        r->p += n;
        return 0;
    }

    /* ByteRun1: control byte c (signed):
     *   0..127   -> copy next c+1 bytes literally
     *   -1..-127 -> replicate next byte (-c)+1 times
     *   -128     -> no-op */
    int produced = 0;
    while (produced < n) {
        if (r->p >= r->end)
            return -1;
        int8_t c = (int8_t)*r->p++;
        if (c >= 0) {
            int cnt = c + 1;
            if (produced + cnt > n || r->p + cnt > r->end)
                return -1;
            memcpy(dst + produced, r->p, (size_t)cnt);
            r->p += cnt;
            produced += cnt;
        } else if (c != -128) {
            int cnt = (-c) + 1;
            if (produced + cnt > n || r->p >= r->end)
                return -1;
            memset(dst + produced, *r->p++, (size_t)cnt);
            produced += cnt;
        }
        /* c == -128: nothing */
    }
    return 0;
}

void image_free(image_t *img)
{
    if (img) {
        free(img->pixels);
        img->pixels = NULL;
    }
}

int ilbm_decode(const ilbm_file_t *f, image_t *img, const char **err)
{
    const bmhd_t *b = &f->bmhd;
    int w = b->w, h = b->h;
    int nPlanes = b->nPlanes;

    memset(img, 0, sizeof *img);

    if (w <= 0 || h <= 0) {
        *err = "invalid image dimensions";
        return -1;
    }
    if (b->compression > cmpByteRun1) {
        *err = "unsupported compression method";
        return -1;
    }
    if (!((nPlanes >= 1 && nPlanes <= 8) || nPlanes == 24 || nPlanes == 32)) {
        *err = "unsupported number of bitplanes";
        return -1;
    }
    if ((long long)w * h > 64LL * 1024 * 1024) {
        *err = "image dimensions too large";
        return -1;
    }

    int rowBytes = ((w + 15) / 16) * 2;
    int maskPlane = (b->masking == mskHasMask) ? 1 : 0;
    int totalPlanes = nPlanes + maskPlane;
    int is_deep = (nPlanes == 24 || nPlanes == 32);

    /* --- Build the normalised palette (with the OCS 12-bit fix) --------- */
    uint8_t pal[256][3];
    memset(pal, 0, sizeof pal);
    int ncolors = f->has_cmap ? f->ncolors : 0;

    /* Classic OCS/ECS files store 4-bit-per-gun colours in the high nibble,
     * leaving every low nibble zero. Detect that and replicate the nibble so
     * colours span the full 0..255 range instead of appearing too dark. */
    int ocs_fix = ncolors > 0;
    for (int i = 0; i < ncolors * 3; i++) {
        if (f->cmap[i] & 0x0F) {
            ocs_fix = 0;
            break;
        }
    }
    for (int i = 0; i < ncolors; i++) {
        uint8_t r  = f->cmap[i * 3 + 0];
        uint8_t g  = f->cmap[i * 3 + 1];
        uint8_t bl = f->cmap[i * 3 + 2];
        if (ocs_fix) {
            r  = (uint8_t)((r  & 0xF0) | (r  >> 4));
            g  = (uint8_t)((g  & 0xF0) | (g  >> 4));
            bl = (uint8_t)((bl & 0xF0) | (bl >> 4));
        }
        pal[i][0] = r;
        pal[i][1] = g;
        pal[i][2] = bl;
    }

    /* --- Resolve the display mode from CAMG (with sanity checks) -------- */
    uint32_t camg = f->has_camg ? f->camg : 0;
    int is_ham = f->has_camg && (camg & CAMG_HAM);
    int is_ehb = f->has_camg && (camg & CAMG_EHB);

    /* When there is no CAMG, a 6-plane image with a 32-entry palette is the
     * classic Extra-Half-Brite signature. */
    if (!f->has_camg && nPlanes == 6 && ncolors == 32)
        is_ehb = 1;

    /* Cross-validate against the plane count; junk CAMG bits are dropped. */
    if (is_ham && !(nPlanes == 6 || nPlanes == 8))
        is_ham = 0;
    if (is_ehb && nPlanes != 6)
        is_ehb = 0;
    if (is_ham)
        is_ehb = 0;             /* HAM wins if both bits somehow appear */

    /* --- Allocate output and decode ------------------------------------ */
    uint32_t *pixels = malloc((size_t)w * h * sizeof *pixels);
    uint8_t  *planebuf = malloc((size_t)totalPlanes * rowBytes);
    if (!pixels || !planebuf) {
        free(pixels);
        free(planebuf);
        *err = "out of memory";
        return -1;
    }

    body_reader_t rd = {
        f->body, f->body + f->body_len, b->compression == cmpByteRun1
    };

    for (int y = 0; y < h; y++) {
        for (int p = 0; p < totalPlanes; p++) {
            if (read_row(&rd, planebuf + (size_t)p * rowBytes, rowBytes) != 0) {
                free(pixels);
                free(planebuf);
                *err = "truncated or corrupt BODY data";
                return -1;
            }
        }

        uint32_t *dst = pixels + (size_t)y * w;

        if (is_deep) {
            /* 24/32 planes: direct RGB, planes 0-7=R, 8-15=G, 16-23=B. */
            for (int x = 0; x < w; x++) {
                int byte = x >> 3, bit = 7 - (x & 7);
                uint8_t comp[4] = { 0, 0, 0, 0 };
                for (int p = 0; p < nPlanes; p++) {
                    int v = (planebuf[(size_t)p * rowBytes + byte] >> bit) & 1;
                    comp[p >> 3] |= (uint8_t)(v << (p & 7));
                }
                dst[x] = 0xFF000000u |
                         ((uint32_t)comp[0] << 16) |
                         ((uint32_t)comp[1] << 8) |
                         (uint32_t)comp[2];
            }
            continue;
        }

        /* Indexed / EHB / HAM. HAM holds colour across the row, starting from
         * colour register 0 at the left edge. */
        int hr = pal[0][0], hg = pal[0][1], hb = pal[0][2];

        for (int x = 0; x < w; x++) {
            int byte = x >> 3, bit = 7 - (x & 7);
            int idx = 0;
            for (int p = 0; p < nPlanes; p++) {
                int v = (planebuf[(size_t)p * rowBytes + byte] >> bit) & 1;
                idx |= v << p;
            }

            uint8_t r, g, bl;
            if (is_ham && nPlanes == 6) {
                int ctrl = idx >> 4;        /* bits 5,4 */
                int data = idx & 0x0F;
                if (ctrl == 0) {
                    hr = pal[data][0]; hg = pal[data][1]; hb = pal[data][2];
                } else {
                    int v = data * 0x11;    /* 4-bit -> 8-bit */
                    if (ctrl == 1)      hb = v;   /* modify blue  */
                    else if (ctrl == 2) hr = v;   /* modify red   */
                    else                hg = v;   /* modify green */
                }
                r = hr; g = hg; bl = hb;
            } else if (is_ham && nPlanes == 8) {
                int ctrl = idx >> 6;        /* bits 7,6 */
                int data = idx & 0x3F;
                if (ctrl == 0) {
                    hr = pal[data][0]; hg = pal[data][1]; hb = pal[data][2];
                } else {
                    int v = (data << 2) | (data >> 4);  /* 6-bit -> 8-bit */
                    if (ctrl == 1)      hb = v;
                    else if (ctrl == 2) hr = v;
                    else                hg = v;
                }
                r = hr; g = hg; bl = hb;
            } else if (is_ehb) {
                int base = idx & 0x1F;
                if (idx & 0x20) {           /* half-bright register */
                    r  = pal[base][0] >> 1;
                    g  = pal[base][1] >> 1;
                    bl = pal[base][2] >> 1;
                } else {
                    r = pal[base][0]; g = pal[base][1]; bl = pal[base][2];
                }
            } else {
                r = pal[idx][0]; g = pal[idx][1]; bl = pal[idx][2];
            }

            dst[x] = 0xFF000000u |
                     ((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)bl;
        }
    }

    free(planebuf);

    /* --- Authentic Amiga display aspect -------------------------------- */
    int pax, pay;
    if (b->xAspect > 0 && b->yAspect > 0) {
        /* Spec-sanctioned pixel aspect; the accurate common case. */
        pax = b->xAspect;
        pay = b->yAspect;
    } else {
        /* No aspect metadata: assume a square lores pixel, then correct for
         * hi-res (half width) and interlace (half height) so those images keep
         * the same physical proportions as their lores equivalent. */
        pax = (camg & CAMG_HIRES) ? 1 : 2;
        pay = (camg & CAMG_LACE)  ? 1 : 2;
    }

    img->w = w;
    img->h = h;
    img->pixels = pixels;
    img->aspect_num = w * pax;
    img->aspect_den = h * pay;
    return 0;
}

