    (0x3e, 0xb8, 0x49),
    (0x74, 0xd0, 0x7d),
    (0x59, 0x55, 0xe0),
    (0x80, 0x76, 0xf1),
    (0xb9, 0x5e, 0x51),
    (0x65, 0xdb, 0xef),
    (0xdb, 0x65, 0x59),
    (0xff, 0x89, 0x7d),
    (0xcc, 0xc3, 0x5e),
    (0xde, 0xd0, 0x87),
    (0x3a, 0xa2, 0x41),
    (0xb7, 0x66, 0xb5),
    (0xcc, 0xcc, 0xcc),
    (0xff, 0xff, 0xff)
    ]

def get_color_index(col):
    diff_sum = 256 * 3
    idx = 1
    cnt = 0
    for c in msx_palette:
        sum = abs(col[0] - c[0]) + abs(col[1] - c[1]) + abs(col[2] - c[2])
        if sum <= diff_sum:
            idx = cnt
            diff_sum = sum
        cnt = cnt + 1
    return idx

