{
	return m_Set[sprite][index];
}

void CSpritesSet::SetValue( int sprite, int index, int value )
{
	int i;


	for( i = 0; i < 4; i++ )
	{
		if( i == sprite ) m_Set[i][index] = value;
		else 
		{
			if( value )	m_Set[i][index] = 0;
		}
	}
}


